recipes.code:
{
  "inputs": [
    {
      "id": "vibevo-api-key",
      "type": "promptString",
      "description": "VibeVO Public API key (vibevo_live_...). Mint it in the VibeVO cabinet with the scopes the agent needs.",
      "password": true
    }
  ],
  "servers": {
    "vibevo": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@vibevo/mcp@0.1.2"
      ],
      "env": {
        "VIBEVO_API_KEY": "${input:vibevo-api-key}",
        "VIBEVO_API_BASE_URL": "https://api.vibevo.io"
      }
    }
  }
}
